class SYSTEM_FILETIME(ctypes.Structure):
    _fields_ = [('low', ctypes.c_uint), ('high', ctypes.c_uint)]


class MEMORYSTATUSEX(ctypes.Structure):
    _fields_ = [('dwLength', ctypes.c_ulong), ('dwMemoryLoad', ctypes.c_ulong),
                ('ullTotalPhys', ctypes.c_ulonglong), ('ullAvailPhys', ctypes.c_ulonglong),
                ('ullTotalPageFile', ctypes.c_ulonglong), ('ullAvailPageFile', ctypes.c_ulonglong),
                ('ullTotalVirtual', ctypes.c_ulonglong), ('ullAvailVirtual', ctypes.c_ulonglong),
                ('ullAvailExtendedVirtual', ctypes.c_ulonglong)]


def available_physical_memory_bytes():
    if os.name != 'nt':
        return None
    try:
        kernel = ctypes.WinDLL('kernel32', use_last_error=True)
        function = kernel.GlobalMemoryStatusEx
        function.argtypes = [ctypes.POINTER(MEMORYSTATUSEX)]
        function.restype = ctypes.c_int
        status = MEMORYSTATUSEX()
        status.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
        if not function(ctypes.byref(status)):
            return None
        value = int(status.ullAvailPhys)
        return value if value > 0 else None
    except Exception:
        return None


def storage_resource_snapshot(folder):
    path = pathlib.Path(folder)
    try:
        usage = shutil.disk_usage(path)
        total = int(usage.total)
        free = int(usage.free)
    except (OSError, ValueError, TypeError):
        total = None
        free = None
    persistent = 0
    pending = [path]
    while pending:
        current = pending.pop()
        try:
            with os.scandir(current) as entries:
                for entry in entries:
                    try:
                        if entry.is_symlink():
                            continue
                        if entry.is_file(follow_symlinks=False):
                            persistent += int(entry.stat(follow_symlinks=False).st_size)
                        elif entry.is_dir(follow_symlinks=False):
                            pending.append(pathlib.Path(entry.path))
                    except OSError:
                        continue
        except OSError:
            continue
    fraction = free / total if free is not None and total is not None and total > 0 else None
    factor = max(0.0, min(1.0, fraction)) if fraction is not None else 0.0
    return {'disk_total_bytes': total, 'disk_free_bytes': free,
            'persistent_data_bytes': persistent,
            'disk_free_fraction': fraction,
            'storage_capacity_factor': factor}


def system_cpu_load():
    global _SYSTEM_CPU_API, _SYSTEM_CPU_SAMPLE
    if os.name != 'nt':
        return None
    try:
        with _SYSTEM_CPU_LOCK:
            if _SYSTEM_CPU_API is None:
                kernel = ctypes.WinDLL('kernel32', use_last_error=True)
                function = kernel.GetSystemTimes
                function.argtypes = [ctypes.POINTER(SYSTEM_FILETIME)] * 3
                function.restype = ctypes.c_int
                _SYSTEM_CPU_API = function
            idle, kernel_time, user_time = SYSTEM_FILETIME(), SYSTEM_FILETIME(), SYSTEM_FILETIME()
            if not _SYSTEM_CPU_API(ctypes.byref(idle), ctypes.byref(kernel_time), ctypes.byref(user_time)):
                return None
            current = tuple((int(item.high) << 32) | int(item.low) for item in (idle, kernel_time, user_time))
            previous = _SYSTEM_CPU_SAMPLE
            _SYSTEM_CPU_SAMPLE = current
            if previous is None:
                return None
            idle_delta = current[0] - previous[0]
            total_delta = current[1] - previous[1] + current[2] - previous[2]
            if total_delta <= 0 or idle_delta < 0:
                return None
            return max(0.0, min(1.0, 1.0 - idle_delta / total_delta))
    except Exception:
        return None


def set_current_thread_priority(priority):
    if os.name != 'nt':
        return False
    try:
        kernel = ctypes.WinDLL('kernel32', use_last_error=True)
        kernel.GetCurrentThread.restype = ctypes.c_void_p
        kernel.SetThreadPriority.argtypes = [ctypes.c_void_p, ctypes.c_int]
        kernel.SetThreadPriority.restype = ctypes.c_int
        return bool(kernel.SetThreadPriority(kernel.GetCurrentThread(), int(priority)))
    except Exception:
        return False


def set_current_process_background_priority():
    if os.name != 'nt':
        return False
    try:
        kernel = ctypes.WinDLL('kernel32', use_last_error=True)
        kernel.GetCurrentProcess.restype = ctypes.c_void_p
        kernel.SetPriorityClass.argtypes = [ctypes.c_void_p, ctypes.c_uint]
        kernel.SetPriorityClass.restype = ctypes.c_int
        return bool(kernel.SetPriorityClass(kernel.GetCurrentProcess(), 0x00004000))
    except Exception:
        return False
