def action_elapsed_seconds(detail, reference_seconds=None):
    if not isinstance(detail, dict):
        return TIME_REFERENCE_SECONDS if reference_seconds is None else reference_seconds
    fallback = detail.get('feedback_reference_seconds', reference_seconds)
    if not isinstance(fallback, (int, float)) or not math.isfinite(float(fallback)) or float(fallback) <= 0.0:
        fallback = TIME_REFERENCE_SECONDS
    value = detail.get('effective_elapsed_seconds', detail.get('duration', detail.get('requested_duration', fallback)))
    try:
        seconds = float(value)
    except (ValueError, TypeError, OverflowError):
        return float(fallback)
    return max(0.03, seconds) if math.isfinite(seconds) else float(fallback)


def transition_time_reference(transition):
    if len(transition) > 9 and isinstance(transition[9], dict):
        value = transition[9].get('feedback_reference_seconds')
        try:
            value = float(value)
            if math.isfinite(value) and value > 0.0:
                return max(0.01, value)
        except (ValueError, TypeError, OverflowError):
            pass
    return TIME_REFERENCE_SECONDS


def transition_elapsed_seconds(transition, reference_seconds=None):
    reference = transition_time_reference(transition) if reference_seconds is None else reference_seconds
    try:
        reference = max(0.01, float(reference))
    except (ValueError, TypeError, OverflowError):
        reference = TIME_REFERENCE_SECONDS
    if len(transition) > 9 and isinstance(transition[9], dict):
        data = transition[9]
        if 'cumulative_elapsed_seconds' in data:
            try:
                value = float(data['cumulative_elapsed_seconds'])
                if math.isfinite(value):
                    return max(0.03, value)
            except (ValueError, TypeError, OverflowError):
                pass
        return action_elapsed_seconds(data, reference) * max(1, int(transition[7])) if 'effective_elapsed_seconds' not in data and int(transition[7]) > 1 else action_elapsed_seconds(data, reference)
    return max(1, int(transition[7])) * reference


def temporal_discount(seconds, reference_seconds=None):
    reference = TIME_REFERENCE_SECONDS if reference_seconds is None else max(0.01, float(reference_seconds))
    return DISCOUNT ** (max(0.0, float(seconds)) / reference)


def long_goal_discount(seconds, reference_seconds=None):
    reference = TIME_REFERENCE_SECONDS if reference_seconds is None else max(0.01, float(reference_seconds))
    return LONG_GOAL_DISCOUNT ** (max(0.0, float(seconds)) / reference)


def feedback_time_reference(game):
    values = []
    try:
        current = float(game.feedback_delay)
        if math.isfinite(current) and current > 0.0:
            values.append(current)
    except (AttributeError, TypeError, ValueError, OverflowError):
        pass
    for record in getattr(game, 'feedback_latency_by_kind', {}).values():
        if isinstance(record, (list, tuple)) and len(record) >= 2:
            try:
                if int(record[1]) > 0:
                    value = float(record[0])
                    if math.isfinite(value) and value > 0.0:
                        values.append(value)
            except (TypeError, ValueError, OverflowError):
                pass
    if not values:
        return TIME_REFERENCE_SECONDS
    values.sort()
    middle = len(values) // 2
    median = values[middle] if len(values) % 2 else (values[middle - 1] + values[middle]) * 0.5
    return max(0.01, median)


def supported_goal_training(transition):
    detail = transition[9] if len(transition) > 9 and isinstance(transition[9], dict) else {}
    if detail.get('feedback_valid') is False:
        return 0.0, 0.0
    credit = bool(detail.get('outcome_credit'))
    result = detail.get('learning_screen_result') in ('win', 'task', 'loss')
    tier = detail.get('learning_objective_tier')
    evidence = float(detail.get('learning_goal_confidence') or 0.0)
    if credit:
        evidence = max(evidence, float(detail.get('credit_confidence') or 0.0))
    if not (credit or result or (tier == 'calibrated_proxy' and evidence >= 0.34)):
        return 0.0, 0.0
    try:
        signal = (float(transition[3]) if credit else
                  float(detail.get('nstep_goal_signal', detail.get('learning_objective_signal', 0.0))))
        reliability = max(0.0, min(1.0, evidence))
        if not math.isfinite(signal) or reliability < 0.20:
            return 0.0, 0.0
    except (TypeError, ValueError, OverflowError):
        return 0.0, 0.0
    if result or credit:
        reliability = max(reliability, 0.65)
    elif tier == 'calibrated_proxy':
        reliability *= 0.65
    return max(-1.0, min(1.0, signal)), min(1.0, reliability)

def temporal_response_confidence(frame_deltas, interval_deltas, passive, stability):
    clean = [max(0.0, float(value)) for value in frame_deltas
             if isinstance(value, (int, float)) and math.isfinite(value)]
    if len(clean) < 2:
        return 0.50
    peak = max(clean)
    settled = clean[-1]
    natural = max(0.0, float(passive)) if isinstance(passive, (int, float)) and math.isfinite(passive) else 0.0
    if peak < max(0.006, natural * 1.15):
        return 0.50
    retained = max(0.0, min(1.0, (settled - natural * 0.5) / max(0.012, peak)))
    clean_intervals = [max(0.0, float(value)) for value in interval_deltas
                       if isinstance(value, (int, float)) and math.isfinite(value)]
    ongoing = (sorted(clean_intervals)[len(clean_intervals) // 2] if clean_intervals else 0.0)
    drift = max(0.0, min(1.0, ongoing / max(0.012, peak)))
    steady = max(0.0, min(1.0, float(stability))) if isinstance(stability, (int, float)) and math.isfinite(stability) else 0.0
    return max(0.20, min(1.0, 0.25 + 0.35 * retained + 0.27 * steady + 0.13 * (1.0 - drift)))


def adaptive_visual_thresholds(game, natural_change, elapsed_seconds, point_count):
    natural = float(natural_change) if isinstance(natural_change, (int, float)) and math.isfinite(float(natural_change)) else 0.0
    elapsed = float(elapsed_seconds) if isinstance(elapsed_seconds, (int, float)) and math.isfinite(float(elapsed_seconds)) else 0.0
    natural = max(0.0, natural)
    elapsed = max(0.0, elapsed)
    rates = []
    deviations = []
    if game is not None:
        timed_records = getattr(game, 'passive_timed', {})
        if not hasattr(timed_records, 'values'):
            timed_records = {}
        for record in timed_records.values():
            if not isinstance(record, (list, tuple)) or len(record) < 3:
                continue
            try:
                rate = float(record[0])
                variance = float(record[1])
                count = int(record[2])
                if count > 0 and math.isfinite(rate) and math.isfinite(variance) and variance >= 0.0:
                    rates.append(max(0.0, rate))
                    deviations.append(math.sqrt(variance))
            except (TypeError, ValueError, OverflowError):
                continue
    if rates:
        rates.sort()
        deviations.sort()
        middle = len(rates) // 2
        baseline_rate = rates[middle] if len(rates) % 2 else (rates[middle - 1] + rates[middle]) * 0.5
        middle = len(deviations) // 2
        deviation_rate = deviations[middle] if len(deviations) % 2 else (deviations[middle - 1] + deviations[middle]) * 0.5
    else:
        baseline_rate = natural / elapsed if elapsed > 0.0 else natural
        deviation_rate = baseline_rate
    try:
        passive_value = float(getattr(game, 'passive_change', 0.0) or 0.0) if game is not None else 0.0
    except (TypeError, ValueError, OverflowError):
        passive_value = 0.0
    passive = max(natural, passive_value if math.isfinite(passive_value) else 0.0)
    expected_noise = max(passive, baseline_rate * elapsed)
    uncertainty = deviation_rate * elapsed
    floor = 1.0 / 765.0
    global_threshold = min(1.0, max(floor, expected_noise + uncertainty))
    regional_threshold = min(1.0, max(global_threshold,
        expected_noise + uncertainty * math.sqrt(2.0 * math.log(13.0))))
    focus_trials = max(2, int(point_count) + 1)
    focused_threshold = min(1.0, max(global_threshold,
        expected_noise + uncertainty * math.sqrt(2.0 * math.log(focus_trials))))
    return {'global': global_threshold, 'regional': regional_threshold, 'focused': focused_threshold}


def camera_frame_alignment(before, after):
    if not isinstance(before, (bytes, bytearray)) or not isinstance(after, (bytes, bytearray)) or len(before) != W * H * 4 or len(after) != len(before):
        return (0.0, (0, 0), 0.0)
    coordinates = tuple((x, y) for y in range(20, H - 20, 11) for x in range(20, W - 20, 11))
    base = tuple((before[(y * W + x) * 4 + 1] * 2 + before[(y * W + x) * 4]
                  + before[(y * W + x) * 4 + 2]) for x, y in coordinates)
    candidates = (-12, -8, -4, 0, 4, 8, 12)
    no_shift = None
    best = (float('inf'), 0, 0)
    for dy in candidates:
        for dx in candidates:
            total = 0
            for (x, y), initial in zip(coordinates, base):
                offset = ((y + dy) * W + x + dx) * 4
                total += abs(initial - (after[offset + 1] * 2 + after[offset] + after[offset + 2]))
            mean = total / max(1, len(coordinates) * 1020)
            if dx == 0 and dy == 0:
                no_shift = mean
            if mean < best[0]:
                best = (mean, dx, dy)
    original = no_shift if no_shift is not None else best[0]
    confidence = max(0.0, min(1.0, (original - best[0]) / max(0.02, original)))
    if best[1:] == (0, 0) or original < 0.035:
        confidence = 0.0
    return best[0], (best[1], best[2]), confidence


def action_response_evidence(samples, passive, pre_action, drift, stability, sample_times=None):
    clean = [max(0.0, float(v)) for v in samples if isinstance(v, (float, int)) and math.isfinite(v)]
    if len(clean) < 2:
        return 0.0
    floor = max(0.005, max(0.0, passive) * 1.7, max(0.0, pre_action) * 0.85,
                min(max(clean), max(0.0, drift)) * 0.55)
    peak = max(clean)
    surplus = max(0.0, peak - floor)
    retention = max(0.0, min(1.0, (clean[-1] - floor * 0.40) / max(0.015, peak)))
    timing = 1.0
    if isinstance(sample_times, (tuple, list)) and len(sample_times) == len(clean):
        if clean.index(peak) == 0 and drift > peak * 0.50:
            timing *= 0.72
    return max(0.0, min(1.0, surplus / max(0.015, peak) *
                         (0.30 + 0.35 * retention + 0.35 * max(0.0, min(1.0, stability))) * timing))


