class LocalGlyphTemplates:
    def __init__(self):
        self.templates = {}
        if os.name != 'nt':
            return
        gdi = ctypes.WinDLL('gdi32', use_last_error=True)
        gdi.CreateFontW.argtypes = [ctypes.c_int] * 13 + [ctypes.c_wchar_p]
        gdi.CreateFontW.restype = HWND
        gdi.TextOutW.argtypes = [HWND, ctypes.c_int, ctypes.c_int, ctypes.c_wchar_p, ctypes.c_int]
        gdi.TextOutW.restype = ctypes.c_int
        gdi.SetTextColor.argtypes = [HWND, ctypes.c_ulong]
        gdi.SetTextColor.restype = ctypes.c_ulong
        gdi.SetBkMode.argtypes = [HWND, ctypes.c_int]
        gdi.SetBkMode.restype = ctypes.c_int
        gdi.CreateCompatibleDC.argtypes = [HWND]
        gdi.CreateCompatibleDC.restype = HWND
        gdi.DeleteDC.argtypes = [HWND]
        gdi.DeleteDC.restype = ctypes.c_int
        gdi.CreateDIBSection.argtypes = [HWND, ctypes.POINTER(BITMAPINFO), ctypes.c_uint, ctypes.POINTER(HWND), HWND, ctypes.c_ulong]
        gdi.CreateDIBSection.restype = HWND
        gdi.SelectObject.argtypes = [HWND, HWND]
        gdi.SelectObject.restype = HWND
        gdi.DeleteObject.argtypes = [HWND]
        gdi.DeleteObject.restype = ctypes.c_int
        dc = gdi.CreateCompatibleDC(None)
        if not dc:
            return
        dib = BITMAPINFO()
        dib.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        dib.bmiHeader.biWidth = 40
        dib.bmiHeader.biHeight = -40
        dib.bmiHeader.biPlanes = 1
        dib.bmiHeader.biBitCount = 32
        pointer = HWND()
        bitmap = gdi.CreateDIBSection(dc, ctypes.byref(dib), 0, ctypes.byref(pointer), None, 0)
        if not bitmap or not pointer.value:
            if bitmap:
                gdi.DeleteObject(bitmap)
            gdi.DeleteDC(dc)
            return
        old_bitmap = gdi.SelectObject(dc, bitmap)
        gdi.SetBkMode(dc, 1)
        gdi.SetTextColor(dc, 0xFFFFFF)
        chars = ('胜利失败通关成功任务完成获游戏结束恭喜挑战胜负已达标战败继续重试重新开始'
                 '暂停恢复返回菜单选择确认确定取消开始进入下一关再来一次关卡任务目标等级'
                 '生命血量护甲魔力能量时间积分得分分数金币钻石奖励成就解锁经验升级'
                 '装备道具背包使用购买出售获得领取接受拒绝设置选项帮助保存加载'
                 '地图位置角色玩家敌人攻击防御跳跃移动方向左右上下提示注意'
                 '单人多人模式剧情竞技匹配在线离线网络连接商店继续退出'
                 '任意按键点击触摸选中确定暂停请稍候刷新等待错误'
                 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+-:?!/.%')
        try:
            for face in ('Microsoft YaHei UI', 'SimSun', 'Microsoft JhengHei UI', 'Segoe UI', 'Arial', 'Consolas'):
                for height in (14, 18, 24, 31):
                    font = gdi.CreateFontW(height, 0, 0, 0, 650 if height % 2 else 450, 0, 0, 0, 1, 0, 0, 5, 0, face)
                    if not font:
                        continue
                    old_font = gdi.SelectObject(dc, font)
                    try:
                        for char in set(chars):
                            ctypes.memset(pointer.value, 0, 40 * 40 * 4)
                            if not gdi.TextOutW(dc, 2, 1, char, 1):
                                continue
                            bitmap_data = ctypes.string_at(pointer.value, 40 * 40 * 4)
                            positions = [(i % 40, i // 40) for i in range(40 * 40) if bitmap_data[i * 4] >= 95]
                            if not positions:
                                continue
                            left, top = min(x for x, y in positions), min(y for x, y in positions)
                            right, bottom = max(x for x, y in positions), max(y for x, y in positions)
                            occupied = set(positions)
                            mask = set()
                            for y in range(12):
                                sy = top + min(bottom - top, int((y + 0.5) * (bottom - top + 1) / 12))
                                for x in range(10):
                                    sx = left + min(right - left, int((x + 0.5) * (right - left + 1) / 10))
                                    if (sx, sy) in occupied:
                                        mask.add(y * 10 + x)
                            if len(mask) >= 14:
                                variants = self.templates.setdefault(char, [])
                                if not any(2.0 * len(mask & existing) / max(1, len(mask) + len(existing)) >= 0.98
                                           for existing in variants):
                                    variants.append(mask)
                    finally:
                        gdi.SelectObject(dc, old_font)
                        gdi.DeleteObject(font)
        finally:
            gdi.SelectObject(dc, old_bitmap)
            gdi.DeleteObject(bitmap)
            gdi.DeleteDC(dc)
        self.buckets = {}
        for symbol, variants in self.templates.items():
            for shape in variants:
                self.buckets.setdefault(len(shape) // 10, []).append((symbol, shape))

    def best(self, sampled):
        result = (0.0, '')
        second = 0.0
        bucket = len(sampled) // 10
        for offset in range(-2, 3):
            for symbol, shape in getattr(self, 'buckets', {}).get(bucket + offset, []):
                score = 2.0 * len(sampled & shape) / max(1, len(sampled) + len(shape))
                if score > result[0]:
                    if result[1] != symbol:
                        second = max(second, result[0])
                    result = (score, symbol)
                elif symbol != result[1]:
                    second = max(second, score)
        return result if result[0] >= 0.87 and result[0] - second >= 0.055 else (0.0, '')

CAPTURE_OWNER_LOCK = threading.Lock()
HWND = ctypes.c_void_p
LRESULT = ctypes.c_ssize_t
WPARAM = ctypes.c_size_t
LPARAM = ctypes.c_ssize_t
WINPROC = getattr(ctypes, 'WINFUNCTYPE', ctypes.CFUNCTYPE)(LRESULT, HWND, ctypes.c_uint, WPARAM, LPARAM)
HOOKPROC = getattr(ctypes, 'WINFUNCTYPE', ctypes.CFUNCTYPE)(LRESULT, ctypes.c_int, WPARAM, LPARAM)
WNDENUMPROC = getattr(ctypes, 'WINFUNCTYPE', ctypes.CFUNCTYPE)(ctypes.c_int, HWND, LPARAM)


def capture_viewport(rect, width=W, height=H):
    actual_width, actual_height = max(1, int(rect[2])), max(1, int(rect[3]))
    scale = min(width / actual_width, height / actual_height)
    content_width = max(1, min(width, int(round(actual_width * scale))))
    content_height = max(1, min(height, int(round(actual_height * scale))))
    return ((width - content_width) // 2, (height - content_height) // 2,
            content_width, content_height)


def image_point_to_rect(u, v, rect, width=W, height=H):
    ox, oy, content_width, content_height = capture_viewport(rect, width, height)
    source_x = max(0.0, min(1.0, (float(u) * width - ox) / content_width))
    source_y = max(0.0, min(1.0, (float(v) * height - oy) / content_height))
    return source_x, source_y


def compose_capture_frame(frame, width, height, offset_x, offset_y, content_width, content_height):
    if len(frame) != content_width * content_height * 4:
        raise ValueError('采集画面的字节长度错误')
    if offset_x == 0 and offset_y == 0 and content_width == width and content_height == height:
        return frame
    result = bytearray(width * height * 4)
    stride = content_width * 4
    for row in range(content_height):
        start = (offset_y + row) * width * 4 + offset_x * 4
        result[start:start + stride] = frame[row * stride:(row + 1) * stride]
    return bytes(result)


def luminance_bgr(blue, green, red):
    return (blue * 0.114 + green * 0.587 + red * 0.299) / 255.0


