class ExitingProcess:
    def __init__(self):
        self.returncode = None
    def poll(self):
        return self.returncode
    def terminate(self):
        self.returncode = 0
    def kill(self):
        self.returncode = 1
    def wait(self, timeout=None):
        return self.returncode
assert engine.terminate_worker_process(ExitingProcess())
class FakeUser:
    def __init__(self):
        self.pressed = False
        self.accepted = 0
        self.fail_release_count = 0
        self.touch_release_failures = 0
    def GetAsyncKeyState(self, vk):
        return 0x8000 if self.pressed else 0
    def MapVirtualKeyW(self, vk, method):
        return 0
    def SendInput(self, count, data, size):
        packet = engine.ctypes.cast(data, engine.ctypes.POINTER(engine.INPUT)).contents
        is_release = ((packet.type == 1 and packet.value.ki.dwFlags & engine.KEYEVENTF_KEYUP)
                      or (packet.type == 0 and packet.value.mi.dwFlags & (engine.MOUSEEVENTF_LEFTUP | engine.MOUSEEVENTF_RIGHTUP | engine.MOUSEEVENTF_MIDDLEUP | engine.MOUSEEVENTF_XUP)))
        if is_release and self.fail_release_count:
            self.fail_release_count -= 1
            return 0
        self.accepted += count
        return count
    def InjectTouchInput(self, count, infos):
        if infos[0].pressure != 512:
            return 0
        if infos[0].pointerInfo.pointerFlags & 0x40000 and self.touch_release_failures:
            self.touch_release_failures -= 1
            return 0
        return 1
    def GetSystemMetrics(self, code):
        return {76: 0, 77: 0, 78: 1280, 79: 720}[code]
class FakeNative:
    def __init__(self):
        self.user = FakeUser()
