    def render_simulation(position, score):
        pixels = bytearray(bytes((30, 38, 43, 255)) * (engine.W * engine.H))
        for row in range(engine.H):
            tone = 27 if row // 15 % 2 else 18
            for col in range(0, engine.W, 8):
                offset = (row * engine.W + col) * 4
                pixels[offset:offset + 4] = bytes((tone, tone + 7, tone + 13, 255))
        left = max(3, min(engine.W - 39, int(position * engine.W)))
        for row in range(67, 98):
            for col in range(left, left + 32):
                offset = (row * engine.W + col) * 4
                pixels[offset:offset + 4] = bytes((40, 220, 250, 255))
        for row in range(4, 11):
            for col in range(5, 6 + score * 9):
                offset = (row * engine.W + col) * 4
                pixels[offset:offset + 4] = bytes((38, 206, 60, 255))
        return bytes(pixels)
