def stop_options():
    names = {8: 'Backspace', 9: 'Tab', 13: 'Enter', 16: 'Shift', 17: 'Ctrl', 18: 'Alt', 19: 'Pause', 20: 'Caps Lock', 27: 'ESC', 32: 'Space', 33: 'Page Up', 34: 'Page Down', 35: 'End', 36: 'Home', 37: '←', 38: '↑', 39: '→', 40: '↓', 44: 'Print Screen', 45: 'Insert', 46: 'Delete', 91: 'Win Left', 92: 'Win Right', 93: 'Menu', 144: 'Num Lock', 145: 'Scroll Lock'}
    for vk in range(48, 58):
        names[vk] = chr(vk)
    for vk in range(65, 91):
        names[vk] = chr(vk)
    for vk in range(96, 106):
        names[vk] = f'Num {vk - 96}'
    for vk, label in ((106, 'Num *'), (107, 'Num +'), (109, 'Num -'), (110, 'Num .'), (111, 'Num /')):
        names[vk] = label
    for vk in range(112, 136):
        names[vk] = f'F{vk - 111}'
    for vk, label in ((160, 'L Shift'), (161, 'R Shift'), (162, 'L Ctrl'), (163, 'R Ctrl'), (164, 'L Alt'), (165, 'R Alt'), (166, 'Browser Back'), (167, 'Browser Forward'), (168, 'Browser Refresh'), (169, 'Browser Stop'), (170, 'Browser Search'), (171, 'Browser Favorites'), (172, 'Browser Home'), (173, 'Mute'), (174, 'Volume Down'), (175, 'Volume Up'), (176, 'Media Next'), (177, 'Media Previous'), (178, 'Media Stop'), (179, 'Media Play/Pause'), (180, 'Launch Mail'), (181, 'Launch Media'), (182, 'Launch App 1'), (183, 'Launch App 2'), (186, ';'), (187, '='), (188, ','), (189, '-'), (190, '.'), (191, '/'), (192, '`'), (219, '['), (220, '\\'), (221, ']'), (222, "'"), (226, 'OEM 102')):
        names[vk] = label
    ordered = [(names[v], v) for v in [27] + [v for v in sorted(names) if v != 27]]
    return ordered


def encode_png(raw):
    if len(raw) != W * H * 4:
        raise ValueError('无法将非基础分辨率的画面编码为 PNG')
    lines = bytearray()
    for y in range(H):
        lines.append(0)
        base = y * W * 4
        for x in range(W):
            idx = base + x * 4
            lines.extend((raw[idx + 2], raw[idx + 1], raw[idx]))
    def part(tag, data):
        return struct.pack('>I', len(data)) + tag + data + struct.pack('>I', zlib.crc32(tag + data) & 0xFFFFFFFF)
    return b'\x89PNG\r\n\x1a\n' + part(b'IHDR', struct.pack('>IIBBBBB', W, H, 8, 2, 0, 0, 0)) + part(b'IDAT', zlib.compress(bytes(lines), 7)) + part(b'IEND', b'')


def inspect_checkpoint_bundle(folder):
    primary = folder / 'learning_state.json.gz'
    backup = folder / 'learning_state.json.gz.bak'
    delta_path = folder / 'learning_delta.json.gz'
    result = {'files': [], 'snapshot_data': {}, 'restores_latest': False, 'delta_present': delta_path.exists(),
              'delta_valid': False, 'backup_used': False, 'error': None, 'base_step': None, 'latest_step': None}
    def inspect(path, compressed_limit, expanded_limit):
        if path.stat().st_size > compressed_limit:
            raise ValueError('学习检查点压缩容量超限')
        compressed = path.read_bytes()
        if len(compressed) > compressed_limit:
            raise ValueError('学习检查点压缩容量超限')
        with gzip.GzipFile(fileobj=io.BytesIO(compressed), mode='rb') as stream:
            raw = stream.read(expanded_limit + 1)
        if len(raw) > expanded_limit:
            raise ValueError('学习检查点解压容量超限')
        data = json.loads(raw)
        if not isinstance(data, dict):
            raise ValueError('学习检查点结构错误')
        actual_hash = data.pop('integrity_sha256', None)
        payload = json.dumps(data, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode('utf-8')
        if not isinstance(actual_hash, str) or hashlib.sha256(payload).hexdigest() != actual_hash:
            raise ValueError('学习检查点摘要校验失败')
        return data, actual_hash, compressed
    errors = []
    base = None
    base_hash = None
    base_bytes = None
    chosen = None
    for candidate in (primary, backup):
        if not candidate.exists():
            continue
        try:
            proposed, digest, compressed = inspect(candidate, 140_000_000, 260_000_000)
            if (proposed.get('format') != MODEL_FORMAT
                    or proposed.get('feature_count') != FEATURE_COUNT
                    or proposed.get('hidden_size') != MODEL_HIDDEN_SIZE
                    or not isinstance(proposed.get('action_ids'), list)):
                raise ValueError('基础学习检查点版本不匹配')
            base, base_hash, base_bytes, chosen = proposed, digest, compressed, candidate
            break
        except (OSError, ValueError, TypeError, OverflowError, EOFError, gzip.BadGzipFile, zlib.error, json.JSONDecodeError) as exc:
            errors.append(f'{candidate.name}: {type(exc).__name__}: {str(exc)[:120]}')
    if base is None:
        result['error'] = '; '.join(errors)[:300] if errors else 'base_not_found'
        return result
    result['files'] = [chosen]
    result['snapshot_data'][chosen.name] = base_bytes
    result['backup_used'] = chosen == backup
    result['base_step'] = int(base.get('step', 0))
    result['latest_step'] = result['base_step']
    result['base_sha256'] = base_hash
    result['restores_latest'] = not delta_path.exists() and not result['backup_used']
    if delta_path.exists():
        try:
            delta, delta_hash, delta_bytes = inspect(delta_path, 80_000_000, 150_000_000)
            if (delta.get('format') != 2 or delta.get('base_model_format') != MODEL_FORMAT
                    or delta.get('base_step') != result['base_step']
                    or delta.get('feature_count') != base.get('feature_count')
                    or delta.get('hidden_size') != base.get('hidden_size')
                    or delta.get('action_ids') != base.get('action_ids')
                    or not isinstance(delta.get('games'), dict)
                    or int(delta.get('step', -1)) < result['base_step']):
                raise ValueError('增量与基础学习检查点不匹配')
            result['files'].append(delta_path)
            result['snapshot_data'][delta_path.name] = delta_bytes
            result['latest_step'] = int(delta['step'])
            result['delta_valid'] = True
            result['delta_sha256'] = delta_hash
            result['restores_latest'] = not result['backup_used']
        except (OSError, ValueError, TypeError, OverflowError, EOFError, gzip.BadGzipFile, zlib.error, json.JSONDecodeError) as exc:
            errors.append(f'{delta_path.name}: {type(exc).__name__}: {str(exc)[:120]}')
            result['restores_latest'] = False
    if errors:
        result['error'] = '; '.join(errors)[:300]
    return result


def read_blackbox_history(folder, limit=250):
    database = pathlib.Path(folder) / 'experience.sqlite3'
    if not database.is_file():
        return [], None, {}, 'experience_database_not_found'
    address = 'file:' + urllib.parse.quote(str(database.resolve()).replace('\\', '/'), safe='/:') + '?mode=ro'
    connection = None
    try:
        connection = sqlite3.connect(address, uri=True, timeout=1.5)
        connection.execute('PRAGMA query_only=ON')
        connection.execute('BEGIN')
        if int(connection.execute('PRAGMA user_version').fetchone()[0]) != MODEL_FORMAT:
            return [], None, {}, 'experience_database_version_mismatch'
        required = {'at', 'game', 'action', 'reward', 'change', 'done', 'confidence', 'action_detail', 'feature_version'}
        fields = {column[1] for column in connection.execute('PRAGMA table_info(transitions)')}
        image_fields = {column[1] for column in connection.execute('PRAGMA table_info(keyframes)')}
        if not required.issubset(fields) or not {'valid', 'width', 'height', 'frame'}.issubset(image_fields):
            return [], None, {}, 'experience_database_schema_mismatch'
        if connection.execute('SELECT 1 FROM transitions WHERE feature_version<>? LIMIT 1', (MODEL_FORMAT,)).fetchone():
            return [], None, {}, 'experience_database_mixed_versions'
        count = int(connection.execute('SELECT COUNT(*) FROM transitions').fetchone()[0])
        frames = int(connection.execute('SELECT COUNT(*) FROM keyframes').fetchone()[0])
        rows = connection.execute('SELECT at,game,action,reward,change,done,confidence,action_detail FROM transitions ORDER BY id DESC LIMIT ?', (max(1, min(350, int(limit))),)).fetchall()
        actions = []
        detail_fields = ('kind', 'a', 'b', 'x', 'y', 'duration', 'input_sent', 'sent_events', 'interrupted',
                         'interruption_reason', 'feedback_valid', 'response_onset_seconds', 'learning_causality',
                         'learning_action_effect', 'learning_objective_signal', 'learning_information_signal',
                         'learning_objective_tier', 'learning_goal_confidence', 'learning_screen_result',
                         'outcome_credit', 'credit_confidence', 'game_input_received_verified',
                         'game_input_receipt_proven', 'input_dispatch_hook_available',
                         'input_dispatch_expected_by_controller', 'input_dispatch_observed_by_low_level_hook',
                         'input_dispatch_matched_by_low_level_hook', 'input_dispatch_pending_expected',
                         'input_dispatch_pending_observed', 'user_observed_action_support',
                         'early_visual_feedback', 'pre_action_visual_change')
        for at, game, action, reward, change, done, confidence, details in reversed(rows):
            try:
                parsed = json.loads(details) if isinstance(details, str) else {}
            except (ValueError, TypeError, json.JSONDecodeError):
                parsed = {}
            parsed = parsed if isinstance(parsed, dict) else {}
            actions.append({'t': round(float(at), 3), 'game': game, 'action': action,
                            'reward': round(float(reward), 6), 'change': round(float(change), 6),
                            'done': bool(done), 'confidence': round(float(confidence), 4),
                            'detail': {key: parsed[key] for key in detail_fields if key in parsed}})
        picture = None
        for (compressed,) in connection.execute('SELECT frame FROM keyframes WHERE valid=1 AND width=? AND height=? ORDER BY id DESC LIMIT 4', (W, H)):
            try:
                if len(compressed) > W * H * 4 + 4096:
                    continue
                unpacker = zlib.decompressobj()
                pixels = unpacker.decompress(compressed, W * H * 4 + 1)
                if len(pixels) == W * H * 4 and unpacker.eof and not unpacker.unused_data:
                    picture = pixels
                    break
            except (zlib.error, ValueError, TypeError):
                continue
        statistics = {'persisted_transitions': count, 'persisted_keyframes': frames,
                      'latest_recorded_game': actions[-1]['game'] if actions else None,
                      'latest_recorded_action_at': actions[-1]['t'] if actions else None,
                      'recent_actions_available': len(actions), 'screen_from_valid_keyframe': picture is not None,
                      'source': 'current_build_experience.sqlite3'}
        return actions, picture, statistics, None
    except (sqlite3.DatabaseError, OSError, ValueError, TypeError) as exc:
        return [], None, {}, f'{type(exc).__name__}: {str(exc)[:180]}'
    finally:
        if connection is not None:
            connection.close()


